# -*- coding: utf-8 -*-
import os
ROOT=r'D:/repository'
SKIP=('node_modules','dist','.git','build','.hbuilderx','unpackage','backup','bak','archive','.idea','coverage')

def walkfiles():
    for dp,dns,fns in os.walk(ROOT):
        dns[:]=[d for d in dns if d not in SKIP]
        for fn in fns: yield os.path.join(dp,fn)

def dump_context(p, symbols, width=90):
    try: c=open(p,encoding='utf-8',errors='ignore').read()
    except: return {}
    out={}
    for s in symbols:
        i=c.find(s)
        out[s]= c[max(0,i-width):i+len(s)+width].replace('\n',' ') if i>=0 else 'N/A'
    return out

# #9 PDF scale: find Type2.vue under FileList
print('=== #9 FileList Type2/FileList.vue ===')
for p in walkfiles():
    if p.replace('\\','/').endswith(('/FileList/Type2.vue','/FileList/FileList.vue')):
        try: c=open(p,encoding='utf-8',errors='ignore').read()
        except: continue
        hit={s:(s in c) for s in ['scrollTop','translate','scale','dpr','zoom']}
        print(' ',p.replace(ROOT,''),hit)

# #11 苏住房C ZsMap.vue
print('=== #11 ZsMap.vue (any) key context ===')
n=0
for p in walkfiles():
    if p.endswith('ZsMap.vue'):
        try: c=open(p,encoding='utf-8',errors='ignore').read()
        except: continue
        hit=[s for s in ['subkey','3SQBZ','key','map.qq.com'] if s in c]
        print(' ',p.replace(ROOT,''),'hits=',hit)
        n+=1
        if n>=8: break

# #1 resolveStaticUrl context in 苏住房C utils/index.js
print('=== #1 resolveStaticUrl context ===')
for p in walkfiles():
    if p.replace('\\','/').endswith('/src/utils/index.js'):
        try: c=open(p,encoding='utf-8',errors='ignore').read()
        except: continue
        if 'resolveStaticUrl' in c:
            print(' ',p.replace(ROOT,''))
            print('   ',dump_context(p,['resolveStaticUrl'])['resolveStaticUrl'][:180])
            break

# #22 苏州V3 login.vue
print('=== #22 login.vue side/contain/cover ===')
for p in walkfiles():
    if p.endswith('views/login.vue'):
        try: c=open(p,encoding='utf-8',errors='ignore').read()
        except: continue
        hit={s:(s in c) for s in ['side','520px','contain','cover','maxPanel','min-height']}
        if hit['520px'] or hit['side']:
            print(' ',p.replace(ROOT,''),hit)

